 5	/**
 6	 * This file is part of the Predator-Prey Simulation.
 7	 *
 8	 * Populates the field with an initial distribution of organisms and
 9	 * registers species colours with the view.
10	 *
11	 * @version 2022.03.02
12	 */
13	public class Populator {
14	
15	    // Probability that a given grid cell contains each species.
16	    // A single random draw per cell is compared against cumulative thresholds,
17	    // so each stated probability is exact (not conditional on prior species).
18	    private static final double LION_CREATION_PROBABILITY         = 0.05;
19	    private static final double ZEBRA_CREATION_PROBABILITY        = 0.05;
20	    private static final double VULTURE_CREATION_PROBABILITY      = 0.05;
21	    private static final double GRASS_CREATION_PROBABILITY        = 0.04;
22	    private static final double GOAT_CREATION_PROBABILITY         = 0.05;
23	    private static final double ELEPHANT_CREATION_PROBABILITY     = 0.05;
24	    private static final double CHEETAH_CREATION_PROBABILITY      = 0.05;
25	    private static final double POISON_BERRIES_CREATION_PROBABILITY = 0.04;
26	
27	    /**
28	     * Constructor for the populator. Registers species colours with the view.
29	     *
30	     * @param view The simulation view to register colours with.
31	     */
32	    public Populator(SimulatorView view) {
33	        view.setColor(Lion.class,        Color.RED);
34	        view.setColor(Cheetah.class,     Color.MAGENTA);
35	        view.setColor(Vulture.class,     Color.ORANGE);
36	        view.setColor(Zebra.class,       Color.BLUE);
37	        view.setColor(Goat.class,        Color.PINK);
38	        view.setColor(Elephant.class,    Color.GRAY);
39	        view.setColor(Grass.class,       Color.GREEN);
40	        view.setColor(PoisonBerry.class, Color.BLACK);
41	    }
42	
43	    /**
44	     * Randomly populate the field with organisms.
45	     * Each cell gets at most one organism, chosen by a single random draw
46	     * compared against cumulative probability thresholds.
47	     *
48	     * @param organisms The list to add newly created organisms to.
49	     * @param field     The field to populate.
50	     */
51	    public void populate(List<Organism> organisms, Field field)
52	    {
53	        Random rand = Randomizer.getRandom();
54	        field.clear();
55	        for(int row = 0; row < field.getDepth(); row++) {
56	            for(int col = 0; col < field.getWidth(); col++) {
57	                Location location = new Location(row, col);
58	                double r = rand.nextDouble();
59	                double cumulative = 0.0;
60	
61	                if (r < (cumulative += LION_CREATION_PROBABILITY)) {
62	                    organisms.add(Lion.spawn(field, location));
63	                } else if (r < (cumulative += ZEBRA_CREATION_PROBABILITY)) {
64	                    organisms.add(Zebra.spawn(field, location));
65	                } else if (r < (cumulative += VULTURE_CREATION_PROBABILITY)) {
66	                    organisms.add(Vulture.spawn(field, location));
67	                } else if (r < (cumulative += GRASS_CREATION_PROBABILITY)) {
68	                    organisms.add(Grass.spawn(field, location));
69	                } else if (r < (cumulative += GOAT_CREATION_PROBABILITY)) {
70	                    organisms.add(Goat.spawn(field, location));
71	                } else if (r < (cumulative += ELEPHANT_CREATION_PROBABILITY)) {
72	                    organisms.add(Elephant.spawn(field, location));
73	                } else if (r < (cumulative += CHEETAH_CREATION_PROBABILITY)) {
74	                    organisms.add(Cheetah.spawn(field, location));
75	                } else if (r < (cumulative += POISON_BERRIES_CREATION_PROBABILITY)) {
76	                    organisms.add(PoisonBerry.spawn(field, location));
77	                }
78	                // else: leave the cell empty
79	            }
80	        }
81	    }
82	}

