 3	/**
 4	 * This file is part of the Predator-Prey Simulation.
 5	 *
 6	 * A predator animal present in the simulation.
 7	 *
 8	 * @version 2022.03.02
 9	 */
10	public abstract class Predator extends HungryAnimal {
11	
12	    private static final Random rand = Randomizer.getRandom();
13	
14	    /**
15	     * Constructor for a predator in the simulation.
16	     *
17	     * @param traits    Species-level configuration for this predator.
18	     * @param foodLevel The initial food level of this predator.
19	     * @param randomAge Whether the predator should have a random age or not.
20	     * @param field     The field in which the predator resides.
21	     * @param location  The location in which the predator spawns into.
22	     */
23	    public Predator(AnimalTraits traits, int foodLevel, boolean randomAge, Field field, Location location) {
24	        super(traits, foodLevel, randomAge, field, location);
25	    }
26	
27	    /**
28	     * Searches adjacent cells for a live Prey to kill and eat.
29	     *
30	     * @return The location of the eaten prey, or null if none found.
31	     */
32	    @Override
33	    public Location findFood() {
34	        Field field = getField();
35	        for (Location where : field.adjacentLocations(getLocation())) {
36	            Organism obj = field.getObjectAt(where);
37	            if (obj instanceof Prey) {
38	                Prey prey = (Prey) obj;
39	                if (prey.isAlive()) {
40	                    prey.setDead();
41	                    return eat(prey) ? where : null;
42	                }
43	            }
44	        }
45	        return null;
46	    }
47	
48	    /**
49	     * Returns the probability this predator eats a kill rather than leaving it.
50	     */
51	    abstract public double getEatingProbability();
52	
53	    /**
54	     * Eats a killed prey with probability given by {@link #getEatingProbability()}.
55	     *
56	     * @param consumable The prey to be eaten.
57	     * @return Whether the prey was consumed.
58	     */
59	    @Override
60	    public boolean eat(Consumable consumable) {
61	        if (rand.nextDouble() <= getEatingProbability()) {
62	            incrementFoodLevel(consumable.getFoodValue());
63	            consumable.setEaten();
64	            return true;
65	        }
66	        return false;
67	    }
68	}
 1	/**
 2	 * This file is part of the Predator-Prey Simulation.
 3	 *
 4	 * A scavenger animal present in the simulation.
 5	 *
 6	 * @version 2022.03.02
 7	 */
 8	public abstract class Scavenger extends HungryAnimal {
 9	
10	    /**
11	     * Constructor for a scavenger in the simulation.
12	     *
13	     * @param traits    Species-level configuration for this scavenger.
14	     * @param foodLevel The initial food level of this scavenger.
15	     * @param randomAge Whether the scavenger should have a random age or not.
16	     * @param field     The field in which the scavenger resides.
17	     * @param location  The location in which the scavenger spawns into.
18	     */
19	    public Scavenger(AnimalTraits traits, int foodLevel, boolean randomAge, Field field, Location location) {
20	        super(traits, foodLevel, randomAge, field, location);
21	    }
22	
23	    /**
24	     * Searches adjacent cells for a dead Prey corpse to eat.
25	     *
26	     * @return The location of the consumed corpse, or null if none found.
27	     */
28	    @Override
29	    public Location findFood() {
30	        Field field = getField();
31	        for (Location where : field.adjacentLocations(getLocation())) {
32	            Organism obj = field.getObjectAt(where);
33	            if (obj instanceof Prey) {
34	                Prey prey = (Prey) obj;
35	                if (!prey.isAlive()) {
36	                    eat(prey);
37	                    return where;
38	                }
39	            }
40	        }
41	        return null;
42	    }
43	
44	    /**
45	     * Unconditionally eats a dead prey corpse.
46	     *
47	     * @param consumable The corpse to be consumed.
48	     * @return true always (scavengers never leave their food).
49	     */
50	    @Override
51	    public boolean eat(Consumable consumable) {
52	        consumable.setEaten();
53	        incrementFoodLevel(consumable.getFoodValue());
54	        return true;
55	    }
56	}

